class Solution {
    public List<String> watchedVideosByFriends(List<List<String>> watchedVideos, List<List<Integer>> friends, int id, int level) {
        int n = friends.size();
        boolean[] visited = new boolean[n];
        Queue<Integer> q = new ArrayDeque<>();
        q.offer(id);
        visited[id] = true;
        for (int l = 0; l < level; l++) {
            int sz = q.size();
            while (sz-- > 0) {
                int u = q.poll();
                for (int v : friends.get(u)) {
                    if (!visited[v]) { visited[v] = true; q.offer(v); }
                }
            }
        }
        Map<String, Integer> cnt = new HashMap<>();
        while (!q.isEmpty()) {
            for (String vid : watchedVideos.get(q.poll())) cnt.merge(vid, 1, Integer::sum);
        }
        List<String> res = new ArrayList<>(cnt.keySet());
        res.sort((a, b) -> {
            int c = Integer.compare(cnt.get(a), cnt.get(b));
            return c != 0 ? c : a.compareTo(b);
        });
        return res;
    }
}

