    const cnt = {};
    for (const u of q) {
        for (const vid of watchedVideos[u]) cnt[vid] = (cnt[vid] || 0) + 1;
    }
    return Object.keys(cnt).sort((a, b) => cnt[a] - cnt[b] || (a < b ? -1 : 1));
};

