class Solution:
    def watchedVideosByFriends(self, watchedVideos: List[List[str]], friends: List[List[int]], id: int, level: int) -> List[str]:
        n = len(friends)
        dist = [-1] * n
        dist[id] = 0
        q = deque([id])
        while q:
            u = q.popleft()
            for v in friends[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        cnt = Counter()
        for u in range(n):
            if dist[u] == level:
                cnt.update(watchedVideos[u])
        return sorted(cnt, key=lambda x: (cnt[x], x))

